import unittest
from candidate import is_palindrome

class TestIsPalindrome(unittest.TestCase):
    def test_empty_string_returns_true(self):
        self.assertTrue(is_palindrome(''))

    def test_single_character_returns_true(self):
        self.assertTrue(is_palindrome('a'))

    def test_even_length_palindrome(self):
        self.assertTrue(is_palindrome('abba'))

    def test_odd_length_palindrome(self):
        self.assertTrue(is_palindrome('abcba'))

    def test_non_palindrome_returns_false(self):
        self.assertFalse(is_palindrome('abcd'))

    def test_case_sensitive_non_palindrome(self):
        self.assertFalse(is_palindrome('AbA'))

    def test_string_with_spaces_palindrome(self):
        self.assertTrue(is_palindrome('a b a'))

    def test_string_with_punctuation_palindrome(self):
        self.assertTrue(is_palindrome('!@#@!'))

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_palindrome(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_palindrome(12321)

    def test_large_string_palindrome(self):
        large_pal = 'a' * 10000 + 'b' + 'a' * 10000
        self.assertTrue(is_palindrome(large_pal))

    def test_large_non_palindrome(self):
        large_non = 'a' * 9999 + 'b' + 'a' * 10001
        self.assertFalse(is_palindrome(large_non))

    def test_non_ascii_palindrome(self):
        self.assertTrue(is_palindrome('ãçññçã'))

    def test_non_ascii_non_palindrome(self):
        self.assertFalse(is_palindrome('ãçñçã'))

if __name__ == '__main__':
    unittest.main()
